questionvariables.text:
hits(L,s,tol) := length(sublist(L, lambda([v], is(abs(v-s) <= tol))));
matchset(L,S,tol) := is(length(L) = length(S)) and every(lambda([s], is(hits(L,s,tol) = 1)), S);
allgenuine(L,S,tol) := every(lambda([v], some(lambda([s], is(abs(v-s) <= tol)), S)), L);
validate_angles(ex) := if (setp(ex) or listp(ex)) and every(lambda([v], numberp(ev(v,simp))), if setp(ex) then listify(ex) else ex) then "" else "Type the angles as numbers inside curly brackets, separated by commas, for example {30, 150}. Do not type the degree sign.";
r1(v) := float(floor(10*v+1/2)/10);
ang1(v) := block([r], r: floor(10*v+1/2), if integerp(r/10) then string(r/10) else string(float(r/10)));
setraw(L) := if L = [] then "\\{\\,\\}" else sconcat("\\{", simplode(map(lambda([v], sconcat(ang1(v), "^\\circ")), sort(L)), ", "), "\\}");
degraw(v) := sconcat(ang1(v), "^\\circ");
setstr(L) := sconcat("\\(", setraw(L), "\\)");
angc(v) := block([al], al: float(acos(v)*180/%pi), if abs(al) < 1e-9 then [0,360] elseif abs(al-180) < 1e-9 then [180] else [al, 360-al]);
angs(v) := block([al], al: float(asin(v)*180/%pi), if abs(al) < 1e-9 then [0,180,360] elseif abs(al-90) < 1e-9 then [90] elseif abs(al+90) < 1e-9 then [270] elseif al > 0 then [al, 180-al] else [180-al, 360+al]);
qroots(A,B,C) := if A = 0 then (if B = 0 then [] else [-C/B]) elseif B^2-4*A*C < 0 then [] else [(-B-sqrt(B^2-4*A*C))/(2*A), (-B+sqrt(B^2-4*A*C))/(2*A)];
inrange(L) := sublist(L, lambda([v], is(abs(float(v)) <= 1+1e-12)));
uniqf(L) := unique(map(lambda([v], float(floor(10000*v+1/2)/10000)), L));
nice(v) := block([r], r: floor(1000*v+1/2)/1000, if integerp(r) then r else float(r));
res2(v) := block([r], r: floor(100*v+1/2)/100, if integerp(r) then string(r) else string(float(r)));
tm(n, s) := if n = 0 then "" elseif n = 1 then sconcat(" + ", s) elseif n = -1 then sconcat(" - ", s) elseif n > 0 then sconcat(" + ", string(n), s) else sconcat(" - ", string(-n), s);
tc(n) := if n = 0 then "" elseif n > 0 then sconcat(" + ", string(n)) else sconcat(" - ", string(-n));
lead(n, s) := if n = 1 then s elseif n = -1 then sconcat("-", s) else sconcat(string(n), s);
validate_values(ex) := if (setp(ex) or listp(ex)) and every(lambda([v], numberp(ev(v,simp))), if setp(ex) then listify(ex) else ex) then "" else "Type the values as numbers inside curly brackets, separated by commas, for example {1/2, -3}.";
/* Design: solve an equation with the identity step by step (cos x as a letter, factorise, solve). The roots are marked as a set, and the impossible root must be rejected. Source: adapted from SMP AS/A2 Core 2, Chapter 7, E2, E3 and Exercise E, Q2. */
badkind(ex) := listp(ex) or setp(ex) or (not atom(ex) and member(op(ex), [">", "<", ">=", "<=", "#", "and", "or", "not", "nounand", "nounor", "nounnot"]));
validate_qc(ex) := if badkind(ex) then "Type one equation in c, for example 2c^2-7c+3=0." elseif every(lambda([v], is(v = c)), listofvars(ex)) and not freeof(c, ex) then "" else "Use the letter c for cos x, for example 2c^2-7c+3=0.";
L: [[2,7,-5],[2,5,1],[3,-4,1],[2,-1,1],[4,7,-2],[4,-5,2],[3,5,-1],[5,-8,-1],[4,-11,-1],[4,5,2]];

ix: 1+rand(10);
p: L[ix][1]; q: L[ix][2]; r: L[ix][3];
eqd: sconcat(lead(p, "\\sin^2 x"), tm(q, "\\cos x"), tc(r), " = 0");
tq: p*c^2 - q*c - (p+r);
tqs: p*c^2 + q*c + (r-p);
/* The "used 1 - cos x" node tests that slip itself, so it does not fire on every linear entry. */
tql: p*(1-c) + q*c + r;
t_lin: tql = 0;
lhsf(t) := float(p*sin(%pi*t/180)^2 + q*cos(%pi*t/180) + r);
rts: qroots(p, -q, -(p+r));
cv: first(inrange(rts));
cb: first(sublist(rts, lambda([v], is(abs(v) > 1))));
al: float(acos(cv)*180/%pi);
sols: angc(cv); solsF: float(sols); solsd: map(r1, sols);
part: [al, 180-al]; partF: float(part);
slipv: inrange(qroots(p, q, r-p));
slipsol: uniqf(flatten(map(angc, slipv))); slipsolF: float(slipsol);
ftc: cv/2;
ftsol: angc(ftc); ftsolF: float(ftsol);
cset: {cv};
bothset: {cv, cb};
slipset: setify(map(lambda([v], float(floor(10000*v+1/2)/10000)), slipv));
ftset: {ftc};
t_eq: tq = 0;
t_mult: -2*tq;
t_slip: tqs = 0;
t_ok: setify(map(r1, sols));
t_part: setify(map(r1, part));
t_slipsol: setify(map(r1, slipsol));
t_ft: setify(map(r1, ftsol));
t_sub: [r1(sols[1])];
t_sup: append(map(r1, sols), [r1(sols[1])+1]);
t_off: setify(map(lambda([v], r1(v)+5), sols));
t_near: setify(map(lambda([v], r1(v)+0.3), sols));
cnear: {float(cv)+0.004};

feedbackvariables.text:
pe: if not atom(ans1) and op(ans1)="=" then lhs(ans1)-rhs(ans1) else ans1;
isprop(u,w) := block([k0], k0: ratsimp(u/w), is(freeof(c,k0) and k0 # 0));
pex: expand(pe);
qdeg: hipow(pex, c);
lr: if qdeg = 2 then qroots(coeff(pex,c,2), coeff(pex,c,1), coeff(pex,c,0)) else [];
lrv: sublist(lr, lambda([v], is(imagpart(float(v)) = 0) and is(abs(float(v)) <= 1)));

pe: if not atom(ans1) and op(ans1)="=" then lhs(ans1)-rhs(ans1) else ans1;
isprop(u,w) := block([k0], k0: ratsimp(u/w), is(freeof(c,k0) and k0 # 0));
pex: expand(pe);
qdeg: hipow(pex, c);
lr: if qdeg = 2 then qroots(coeff(pex,c,2), coeff(pex,c,1), coeff(pex,c,0)) else [];
lrv: sublist(lr, lambda([v], is(imagpart(float(v)) = 0) and is(abs(float(v)) <= 1)));
cl0: if setp(ans2) then listify(ans2) else ans2;
cl: unique(map(lambda([v], float(floor(10000*float(v)+1/2)/10000)), cl0));

sl0: if setp(ans3) then listify(ans3) else ans3;
sl: unique(map(lambda([v], float(floor(100*float(v)+1/2)/100)), sl0));
okset: matchset(sl, solsF, 0.0501);
fsub: is(length(sl) > 0) and allgenuine(sl, solsF, 0.0501) and is(length(sl) < length(solsF));
fsup: allgenuine(solsF, sl, 0.0501) and is(length(sl) > length(solsF));
extras: sublist(sl, lambda([v], not some(lambda([s], is(abs(v-s) <= 0.0501)), solsF)));
outside: sublist(sl, lambda([v], is(v < -0.0001 or v > 360.0001)));
miss360: some(lambda([s], is(abs(s-360) < 0.001)), solsF) and not some(lambda([v], is(abs(v-360) <= 0.0501)), sl);
radn: is(length(sl) > 0) and every(lambda([v], is(abs(v) < 6.3)), sl) and not okset;
resx0: sublist(extras, lambda([v], is(abs(lhsf(v)) >= 0.005)));
resx: makelist(resx0[i], i, 1, min(4, length(resx0)));
resstr: simplode(map(lambda([v], sconcat("\\(x = ", res2(v), "^\\circ\\) gives \\(", res2(lhsf(v)), "\\)")), resx), "; ");
cl0: if setp(ans2) then listify(ans2) else ans2;
cl: unique(map(lambda([v], float(floor(10000*float(v)+1/2)/10000)), cl0));
ftangF: float(uniqf(flatten(map(angc, inrange(cl)))));
